{
  "sql": "WITH ordered_units AS (SELECT oi.product_id, SUM(oi.quantity) AS ordered_units FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY oi.product_id), returned_units AS (SELECT r.product_id, SUM(r.return_quantity) AS returned_units FROM commerce.returns AS r WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY r.product_id) SELECT ou.product_id, ru.returned_units, ou.ordered_units, CAST(ru.returned_units AS NUMERIC) / NULLIF(ou.ordered_units, 0) AS return_ratio FROM ordered_units AS ou INNER JOIN returned_units AS ru ON ou.product_id = ru.product_id ORDER BY 4 DESC NULLS LAST, 1 LIMIT 200",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Calculates the ratio of returned units to ordered units for each product in 2022. It independently aggregates order quantities from order_items (joined with orders for date filtering) and return quantities from returns, then joins these aggregates on product_id to compute the ratio. Results are ordered by the ratio in descending order, with product_id as a tie-breaker."
}

{
  "sql": "SELECT inv.snapshot_date, p.product_id, p.product_name FROM commerce.inventory AS inv INNER JOIN commerce.products AS p ON inv.product_id = p.product_id WHERE inv.stockout_flag = TRUE AND inv.snapshot_date >= $1 AND inv.snapshot_date < $2 AND EXISTS (SELECT 1 FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE oi.product_id = p.product_id AND o.order_date >= $3 AND o.order_date < $4) ORDER BY 1, 2 LIMIT 200",
  "parameters": [
    "2022-12-01",
    "2023-01-01",
    "2022-12-01",
    "2023-01-01"
  ],
  "explanation": "Selects product snapshots from December 2022 where the stockout_flag is true and there exists at least one order item for that product with an order date in December 2022. The query joins inventory to products to get product details and uses a correlated EXISTS subquery to verify order presence without duplicating inventory rows."
}

{
  "sql": "WITH inv_agg AS (SELECT p.category AS category, SUM(i.units_sold) AS inventory_units_sold FROM commerce.inventory AS i INNER JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date >= $1 AND i.snapshot_date < $2 GROUP BY p.category), ord_agg AS (SELECT p.category AS category, SUM(oi.quantity) AS ordered_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $3 AND o.order_date < $4 GROUP BY p.category) SELECT COALESCE(inv_agg.category, ord_agg.category) AS category, inv_agg.inventory_units_sold, ord_agg.ordered_quantity FROM inv_agg FULL JOIN ord_agg ON inv_agg.category = ord_agg.category ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-12-01",
    "2023-01-01",
    "2022-12-01",
    "2023-01-01"
  ],
  "explanation": "Aggregates inventory units_sold and ordered quantities independently for December 2022 by category, then performs a FULL JOIN to compare them, preserving NULLs for categories present in only one source."
}
